189	        /**
190	         * Simple constructor.
191	         * @param observations sampled observations
192	         * @throws NumberIsTooSmallException if the sample is too short or if
193	         * the first guess cannot be computed.
194	         */
195	        public ParameterGuesser(WeightedObservedPoint[] observations) {
196	            if (observations.length < 4) {
197	                throw new NumberIsTooSmallException(LocalizedFormats.INSUFFICIENT_OBSERVED_POINTS_IN_SAMPLE,
198	                                                    observations.length, 4, true);
199	            }
200	
201	            this.observations = observations.clone();
202	        }
