204	        /**
205	         * Estimate a first guess of the coefficients.
206	         *
207	         * @return the guessed coefficients, in the following order:
208	         * <ul>
209	         *  <li>Amplitude</li>
210	         *  <li>Angular frequency</li>
211	         *  <li>Phase</li>
212	         * </ul>
213	         */
