222	         * Sort the observations with respect to the abscissa.
223	         */
224	        private void sortObservations() {
225	            // Since the samples are almost always already sorted, this
226	            // method is implemented as an insertion sort that reorders the
227	            // elements in place. Insertion sort is very efficient in this case.
228	            WeightedObservedPoint curr = observations[0];
229	            for (int j = 1; j < observations.length; ++j) {
230	                WeightedObservedPoint prec = curr;
231	                curr = observations[j];
232	                if (curr.getX() < prec.getX()) {
233	                    // the current element should be inserted closer to the beginning
234	                    int i = j - 1;
235	                    WeightedObservedPoint mI = observations[i];
236	                    while ((i >= 0) && (curr.getX() < mI.getX())) {
237	                        observations[i + 1] = mI;
238	                        if (i-- != 0) {
239	                            mI = observations[i];
240	                        }
241	                    }
242	                    observations[i + 1] = curr;
243	                    curr = observations[j];
244	                }
245	            }
246	        }
